<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue'
import {useRoute,onBeforeRouteLeave} from 'vue-router'
import {api,type Account} from '../../api'
import {amount,incomeStatus,withdrawalStatus,type StoreAccount} from './types'
import AdminListPager from '../../shared/list/AdminListPager.vue'
import AdminStatusBadge from '../../shared/list/AdminStatusBadge.vue'
import AdminSelectionBar from '../../shared/list/AdminSelectionBar.vue'
import AdminSelectedRowsDialog from '../../shared/list/AdminSelectedRowsDialog.vue'
import {useCurrentPageSelection} from '../../shared/list/useCurrentPageSelection'
import AccountHistoryFilters from './AccountHistoryFilters.vue'
import StoreWithdrawalReview from './StoreWithdrawalReview.vue'
import './stores.css'
const props=defineProps<{account:Account;recordId?:string;embedded?:boolean}>()
const route=useRoute(),targetId={get value(){return props.recordId??String(route.params.storeId)}},data=ref<StoreAccount|null>(null),loading=ref(false),error=ref('')
const reviewPanels=ref<{canClose:()=>Promise<boolean>}[]>([])
async function canClose(){for(const panel of reviewPanels.value){if(!await panel.canClose())return false}return true}
defineExpose({canClose})
onBeforeRouteLeave(canClose)
const emptyQuery=()=>({page:1,pageSize:20,search:'',status:'',dateFrom:'',dateTo:''})
const incomeQuery=ref(emptyQuery()),withdrawalQuery=ref(emptyQuery()),comparison=ref(false),comparisonRows=ref<Record<string,unknown>[]>([])
const incomeSelection=useCurrentPageSelection(()=>data.value?.income??[],r=>r.id),withdrawalSelection=useCurrentPageSelection(()=>data.value?.withdrawals??[],r=>r.id)
function params(){const result=new URLSearchParams();for(const [prefix,values] of [['income',incomeQuery.value],['withdrawal',withdrawalQuery.value]] as const)for(const [key,value] of Object.entries(values))result.set(prefix+key[0]!.toUpperCase()+key.slice(1),String(value));return result}
function paginate(kind:'income'|'withdrawal',page:number,pageSize:number){const target=kind==='income'?incomeQuery:withdrawalQuery;target.value={...target.value,page,pageSize};load()}
function query(kind:'income'|'withdrawal'){const target=kind==='income'?incomeQuery:withdrawalQuery;target.value={...target.value,page:1};load()}
function reset(kind:'income'|'withdrawal'){(kind==='income'?incomeQuery:withdrawalQuery).value=emptyQuery();load()}
function compare(kind:'income'|'withdrawal'){comparisonRows.value=kind==='income'?incomeSelection.selectedRows.value.map(r=>({record:r.orderNo,amount:amount(r.storeFen),status:incomeStatus(r.status),reason:r.reason})):withdrawalSelection.selectedRows.value.map(r=>({record:r.id,amount:amount(r.amountFen),status:withdrawalStatus(r.status),reason:r.reason}));comparison.value=true}
let generation=0
async function load(){const current=++generation;loading.value=true;error.value='';data.value=null;comparison.value=false;try{const result=await api<StoreAccount>(`/stores/${encodeURIComponent(String(targetId.value))}/account?${params()}`);if(current===generation)data.value=result}catch(e){if(current===generation)error.value=e instanceof Error?e.message:'账户详情读取失败。'}finally{if(current===generation)loading.value=false}}
function date(value:string|null){return value?new Date(value).toLocaleString('zh-CN'):'—'}
watch(()=>JSON.stringify([targetId.value,props.account.accountId,props.account.permissionCodes]),()=>{incomeQuery.value=emptyQuery();withdrawalQuery.value=emptyQuery();load()},{immediate:true})
onUnmounted(()=>{generation++;data.value=null})
</script>
<template>
<section class="page-content stores-page admin-list-page"><header class="page-heading"><div><h1>{{data?.storeName||'前置仓'}}账户</h1><p>前置仓结算含进货成本与前置仓利润，扣除前置仓承担的运费及餐饮联盟佣金。餐饮佣金由履约前置仓的利润份额承担。收入与提现以实际结算和线下付款记录为准。</p></div><div class="store-actions"><button class="secondary-button" :disabled="loading" @click="load">重新读取账户</button><RouterLink v-if="!embedded" to="/stores/accounts" class="secondary-button">返回账户列表</RouterLink></div></header>
<p v-if="loading" role="status">正在读取账户详情…</p><p v-else-if="error" role="alert">{{error}} <button class="text-button" @click="load">重试</button></p>
<template v-else-if="data"><div v-if="!data.settlementReady" class="notice" role="status">{{data.reason||'结算条件尚未具备，请查看收入明细。'}}</div><dl class="store-balances"><div><dt>待结算</dt><dd>{{amount(data.balance.pendingFen)}}</dd></div><div><dt>可提现</dt><dd>{{amount(data.balance.availableFen)}}</dd></div><div><dt>冻结中</dt><dd>{{amount(data.balance.frozenFen)}}</dd></div><div><dt>已提现</dt><dd>{{amount(data.balance.paidFen)}}</dd></div></dl>
<section class="panel store-section"><h2>收入明细</h2><AccountHistoryFilters v-model="incomeQuery" kind="income" :loading="loading" @query="query('income')" @reset="reset('income')"/><AdminSelectionBar :count="incomeSelection.selectedRows.value.length" :loading="loading" @clear="incomeSelection.clear"><button class="secondary-button" :disabled="!incomeSelection.selectedRows.value.length" @click="compare('income')">对比所选收入</button></AdminSelectionBar><p>筛选与分页只影响历史明细，余额始终完整计算。</p><p>订单完成、超过订单售后期且无处理中售后，才可结算。待人工核对的记录暂不计入可提现余额。</p><p v-if="!data.income.length">{{data.settlementReady?'暂无结算收入明细。前置仓订单完成后将在此展示。':'结算口径待配置，尚未生成收入明细。'}}</p><div v-else class="table-wrap admin-list-table" tabindex="0" aria-label="前置仓收入明细，可横向滚动"><table><thead><tr><th><input type="checkbox" aria-label="选择当前页全部收入" :checked="incomeSelection.allSelected.value" :indeterminate="incomeSelection.indeterminate.value" @change="incomeSelection.togglePage(($event.target as HTMLInputElement).checked)"></th><th>订单</th><th>订单实付</th><th>进货成本</th><th>平台利润</th><th>前置仓承担运费</th><th>扣佣金前结算</th><th>餐饮佣金扣除</th><th>扣佣金后净结算</th><th>结算状态</th><th>可结算时间</th></tr></thead><tbody><tr v-for="item in data.income" :key="item.id"><td><input type="checkbox" :aria-label="`选择收入 ${item.orderNo}`" :checked="incomeSelection.selectedIds.value.includes(item.id)" @change="incomeSelection.toggle(item.id,($event.target as HTMLInputElement).checked)"></td><td><button class="text-button" @click="comparisonRows=[{record:item.orderNo,amount:amount(item.storeFen),status:incomeStatus(item.status),reason:item.reason}];comparison=true">{{item.orderNo}}</button></td><td>{{amount(item.paidFen)}}</td><td>{{item.costFen==null?'待人工核对':amount(item.costFen)}}</td><td>{{item.platformFen==null?'待人工核对':amount(item.platformFen)}}</td><td>{{amount(item.freightFen)}}</td><td>{{(item.beforeDiningFen===undefined?item.storeFen:item.beforeDiningFen)==null?'待人工核对':amount(item.beforeDiningFen===undefined?item.storeFen:item.beforeDiningFen)}}</td><td>{{item.diningCommissionFen===null?'待人工核对':amount(item.diningCommissionFen===undefined?0:item.diningCommissionFen)}}</td><td>{{item.storeFen==null?'待人工核对':amount(item.storeFen)}}</td><td><AdminStatusBadge :status="item.status" :label="incomeStatus(item.status)"/><small v-if="item.reason">{{item.reason}}</small></td><td>{{date(item.availableAt)}}<small v-if="item.settledAt">结算于 {{date(item.settledAt)}}</small></td></tr></tbody></table></div><AdminListPager v-if="data.incomePagination" :page="incomeQuery.page" :page-size="incomeQuery.pageSize" :total="data.incomePagination.total" :loading="loading" @change="(p,s)=>paginate('income',p,s)"/><p v-else class="muted">当前响应缺少历史分页信息，请更新服务端后重新读取。</p></section>
<section class="panel store-section"><h2>提现记录</h2><AccountHistoryFilters v-model="withdrawalQuery" kind="withdrawal" :loading="loading" @query="query('withdrawal')" @reset="reset('withdrawal')"/><AdminSelectionBar :count="withdrawalSelection.selectedRows.value.length" :loading="loading" @clear="withdrawalSelection.clear"><button class="secondary-button" :disabled="!withdrawalSelection.selectedRows.value.length" @click="compare('withdrawal')">对比所选申请</button></AdminSelectionBar><p>前置仓提交申请后冻结对应余额；平台审核通过后线下转账，再登记付款流水。</p><p v-if="!data.withdrawals.length">{{data.withdrawalReady?'暂无提现申请。前置仓可在小程序前置仓中心发起提现。':'提现渠道待配置，暂未开放提现。'}}</p><button v-if="!data.withdrawalReady" class="secondary-button" disabled>提现待配置</button><div class="table-wrap admin-list-table" tabindex="0" aria-label="提现申请列表"><table><thead><tr><th><input type="checkbox" aria-label="选择当前页全部提现" :checked="withdrawalSelection.allSelected.value" :indeterminate="withdrawalSelection.indeterminate.value" @change="withdrawalSelection.togglePage(($event.target as HTMLInputElement).checked)"></th><th>申请</th><th>收款信息</th><th>状态</th><th>说明 / 凭证</th><th>操作</th></tr></thead><tbody><tr v-for="item in data.withdrawals" :key="item.id"><td><input type="checkbox" :aria-label="`选择提现 ${item.id}`" :checked="withdrawalSelection.selectedIds.value.includes(item.id)" @change="withdrawalSelection.toggle(item.id,($event.target as HTMLInputElement).checked)"></td><td>{{amount(item.amountFen)}}<small>{{date(item.createdAt)}} · {{item.id}}</small></td><td>{{item.payeeName}} · {{item.bankName}}<small>{{item.bankAccount}}</small></td><td><AdminStatusBadge :status="item.status" :label="withdrawalStatus(item.status)"/></td><td>{{item.reason||'—'}}<small v-if="item.paidAt">{{date(item.paidAt)}} · {{item.paymentReference}}</small></td><td><StoreWithdrawalReview ref="reviewPanels" :account="account" :store-id="data.storeId" :item="item" @refresh="load"/></td></tr></tbody></table></div><AdminListPager v-if="data.withdrawalPagination" :page="withdrawalQuery.page" :page-size="withdrawalQuery.pageSize" :total="data.withdrawalPagination.total" :loading="loading" @change="(p,s)=>paginate('withdrawal',p,s)"/><p v-else class="muted">当前响应缺少历史分页信息，请更新服务端后重新读取。</p></section>
</template><AdminSelectedRowsDialog v-model="comparison" title="前置仓财务记录对比" :rows="comparisonRows" :columns="[{key:'record',label:'记录'},{key:'amount',label:'金额'},{key:'status',label:'状态'},{key:'reason',label:'说明'}]"/></section>
</template>
